/**
 * Cheerio provider for lightweight HTML scraping
 */

import * as cheerio from 'cheerio';
import type { WebProvider, GetPageOptions, PageResult, ProviderCapabilities } from '../../core/types.js';
import { extractMetadata, extractLinks, extractImages, applySelectors, htmlToText, htmlToMarkdown } from '../../utils/html-utils.js';
import { sanitizeUrl } from '../../utils/validation.js';

export class CheerioProvider implements WebProvider {
  name = 'cheerio';

  capabilities: ProviderCapabilities = {
    formats: ['html', 'markdown', 'text', 'json'],
    javascript: false,
    screenshots: false,
    cookies: false,
    headers: true,
    selectors: true,
    scriptExecution: false
  };

  constructor(private config: { timeout?: number } = {}) {}

  async getPage(url: string, options: GetPageOptions = {}): Promise<PageResult> {
    const startTime = Date.now();
    const sanitizedUrl = sanitizeUrl(url);

    // Fetch HTML
    const response = await fetch(sanitizedUrl, {
      headers: options.headers,
      signal: AbortSignal.timeout(options.timeout || this.config.timeout || 10000)
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }

    let html = await response.text();

    // Apply selectors
    if (options.selectors) {
      html = applySelectors(html, options.selectors);
    }

    // Extract metadata
    const metadata = extractMetadata(html, sanitizedUrl);

    // Convert to requested format
    let content = html;
    const format = options.format || 'html';

    if (format === 'markdown') {
      content = htmlToMarkdown(html);
    } else if (format === 'text') {
      content = htmlToText(html);
    } else if (format === 'json') {
      const $ = cheerio.load(html);
      const jsonData = {
        title: metadata.title,
        body: $('body').text().trim(),
        links: extractLinks(html, sanitizedUrl),
        images: extractImages(html, sanitizedUrl)
      };
      content = JSON.stringify(jsonData, null, 2);
    }

    // Extract links and images if needed
    const links = options.includeLinks ? extractLinks(html, sanitizedUrl) : undefined;
    const images = options.includeImages ? extractImages(html, sanitizedUrl) : undefined;

    return {
      url: sanitizedUrl,
      content,
      metadata,
      links,
      images,
      provider: this.name,
      duration: Date.now() - startTime
    };
  }

  async isAvailable(): Promise<boolean> {
    return true; // Cheerio is always available
  }
}
/**
 * URL utilities for parsing, validation, and manipulation
 */

/**
 * Validate URL
 */
export function isValidUrl(url: string): boolean {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
}

/**
 * Normalize URL
 */
export function normalizeUrl(url: string): string {
  try {
    const parsed = new URL(url);
    // Remove trailing slash
    parsed.pathname = parsed.pathname.replace(/\/$/, '');
    // Sort query parameters
    parsed.searchParams.sort();
    return parsed.toString();
  } catch {
    return url;
  }
}

/**
 * Get domain from URL
 */
export function getDomain(url: string): string {
  try {
    const parsed = new URL(url);
    return parsed.hostname;
  } catch {
    return '';
  }
}

/**
 * Join URL paths
 */
export function joinUrl(base: string, ...paths: string[]): string {
  try {
    const url = new URL(base);
    for (const path of paths) {
      url.pathname = url.pathname.replace(/\/$/, '') + '/' + path.replace(/^\//, '');
    }
    return url.toString();
  } catch {
    return base;
  }
}

/**
 * Extract all URLs from text
 */
export function extractUrls(text: string): string[] {
  const urlRegex = /https?:\/\/[^\s<>"]+/g;
  return text.match(urlRegex) || [];
}

/**
 * Convert relative URL to absolute
 */
export function resolveUrl(base: string, relative: string): string {
  try {
    return new URL(relative, base).toString();
  } catch {
    return relative;
  }
}
"""Static HTML provider for the canonical Python web surface."""

from datetime import datetime
import json
from typing import Dict, Optional

import httpx

from browsefn.core.errors import BrowseFnError
from browsefn.core.types import (
    GetPageOptions,
    PageMetadata,
    PageResult,
    ProviderCapabilities,
)
from browsefn.utils.html_utils import extract_images, extract_links, extract_metadata, extract_text, html_to_markdown


class BeautifulSoupProvider:
    """Static HTML provider exposed under the canonical `cheerio` id."""

    name = "cheerio"
    capabilities = ProviderCapabilities(
        formats=["html", "markdown", "text", "json"],
        javascript=False,
        screenshots=False,
        cookies=True,
        headers=True,
        selectors=False,
        proxy=True,
    )

    async def get_page(self, url: str, options: GetPageOptions) -> PageResult:
        start_time = datetime.now()
        timeout = (options.timeout or 30000) / 1000
        headers = options.headers or {}
        cookies = {
            cookie.name: cookie.value
            for cookie in (options.cookies or [])
        } or None

        client_config: Dict[str, object] = {
            "timeout": timeout,
            "headers": headers,
            "follow_redirects": True,
        }
        if options.proxy:
            client_config["proxy"] = options.proxy

        async with httpx.AsyncClient(**client_config) as client:
            response = await client.get(url, cookies=cookies)
            response.raise_for_status()
            html_content = response.text

        metadata_dict = extract_metadata(html_content)
        metadata = PageMetadata(
            url=url,
            title=metadata_dict.get("title"),
            description=metadata_dict.get("description"),
            keywords=metadata_dict.get("keywords"),
            author=metadata_dict.get("author"),
            favicon=metadata_dict.get("favicon"),
            openGraph=metadata_dict.get("openGraph"),
            twitter=metadata_dict.get("twitter"),
        )

        content_format = options.format or "html"
        if content_format == "html":
            content = html_content
        elif content_format == "markdown":
            content = html_to_markdown(html_content)
        elif content_format == "text":
            content = extract_text(html_content)
        elif content_format == "json":
            content = json.dumps(
                {
                    "title": metadata.title,
                    "description": metadata.description,
                    "links": extract_links(html_content, url),
                    "images": extract_images(html_content, url),
                }
            )
        else:
            raise BrowseFnError("INVALID_ARGUMENT", f"Invalid format: {content_format}")

        duration = (datetime.now() - start_time).total_seconds() * 1000

        return PageResult(
            url=url,
            content=content,
            metadata=metadata,
            links=extract_links(html_content, url) if options.include_links else None,
            images=extract_images(html_content, url) if options.include_images else None,
            provider=self.name,
            duration=duration,
        )

    async def is_available(self) -> bool:
        return True

